 #ifndef WS_CONTAINERS_BLOCK_DEQUE_H
#define WS_CONTAINERS_BLOCK_DEQUE_H

#include <atomic>
#include <chrono>
#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>
#include <utility>

namespace ws {

template <typename T>
class BlockDeque {
public:
  using Clock = std::chrono::steady_clock;
  using duration = Clock::duration;
  using time_point = Clock::time_point;

  BlockDeque(std::size_t capacity) : capacity_(capacity), closed_(false) {
    assert(capacity_ > 0);
  }

  ~BlockDeque() {
    Close();
  }

  void Clear() {
    std::lock_guard<std::mutex> lock(mtx_);
    deq_.clear();
    closed_ = false;
    producer_cond_.notify_all();
    consumer_cond_.notify_all();
  }

  bool Empty() const {
    std::lock_guard<std::mutex> lock(mtx_);
    return deq_.empty() && !closed_;
  }

  bool Full() const {
    std::lock_guard<std::mutex> lock(mtx_);
    return deq_.size() == capacity_ && !closed_;
  }

  std::size_t Size() const {
    std::lock_guard<std::mutex> lock(mtx_);
    return deq_.size();
  }

  std::size_t Capacity() const {
    return capacity_;
  }

  void PushBack(T item) {
    std::unique_lock<std::mutex> lock(mtx_);
    WaitForSpace();
    deq_.push_back(std::move(item));
    Flush();
  }

  void PushFront(T item) {
    std::unique_lock<std::mutex> lock(mtx_);
    WaitForSpace();
    deq_.push_front(std::move(item));
    Flush();
  }

  const T& Front() const {
    std::lock_guard<std::mutex> lock(mtx_);
    return deq_.front();
  }

  const T& Back() const {
    std::lock_guard<std::mutex> lock(mtx_);
    return deq_.back();
  }

  std::optional<T> Pop(std::optional<duration> time_out) {
    std::unique_lock<std::mutex> lock(mtx_);
    if (deq_.empty() || closed_) {
      return std::nullopt;
    }

    if (time_out) {
      if (!consumer_cond_.wait_for(lock, *time_out, [this] { return !deq_.empty() && !closed_; })){
        return std::nullopt; 
      }
    } else {
      consumer_cond_.wait(lock, [this] { return !deq_.empty() && !closed_; });
    }

    T item = std::move(deq_.front());
    deq_.pop_front();
    producer_cond_.notify_one();
    return item;
  }

  void Flush() {
    std::unique_lock<std::mutex> lock(mtx_);
    consumer_cond_.notify_one();
  }

  void Close() {
    std::lock_guard<std::mutex> lock(mtx_);
    closed_ = true;
    deq_.clear();
    producer_cond_.notify_all();
    consumer_cond_.notify_all();
  }

private:
  void WaitForSpace() {
    while (deq_.size() == capacity_) {
      producer_cond_.wait(mtx_, [this] { return deq_.size() < capacity_; });
    }
  }

  std::size_t capacity_;
  std::atomic_bool closed_;
  std::deque<T> deq_;
  std::mutex mtx_;
  std::condition_variable consumer_cond_;
  std::condition_variable producer_cond_;
};

}

#endif // WS_CONTAINERS_BLOCK_DEQUE_H
